def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 2]
    rows = {}
    for r, c in points:
        rows.setdefault(r, []).append(c)
    # The two aligned markers define the horizontal rail.
    rail_rows = [(r, cs) for r, cs in rows.items() if len(cs) >= 2]
    if len(rail_rows) != 1:
        raise ValueError("expected a single row containing the rail markers")
    rail_r, rail_cs = rail_rows[0]
    left, right = min(rail_cs), max(rail_cs)
    for c in range(left, right + 1):
        if out[rail_r][c] == 0:
            out[rail_r][c] = 3
    # Join each remaining marker to the rail along its column.
    for r, c in points:
        if r == rail_r:
            continue
        for rr in range(min(r, rail_r) + 1, max(r, rail_r)):
            if out[rr][c] == 0:
                out[rr][c] = 3
    return out
